/*
 * prog30_escape_unescape.c
 *
 * Re‑implementation of the original program’s observable behaviour.
 * The binary implements two simple utilities:
 *
 *   prog30_escape_unescape escape   <string>
 *   prog30_escape_unescape unescape <string>
 *
 * *escape*   – converts the input string into a C‑style escaped form.
 *              The following characters are escaped:
 *                  '\\'  ->  "\\\\"
 *                  '"'  ->  "\\\""
 *                  '\n' ->  "\\n"
 *                  '\t' ->  "\\t"
 *
 * *unescape* – performs the inverse transformation.  The recognised
 *              escape sequences are the same as above.  Any other
 *              back‑slash sequence (including a trailing back‑slash)
 *              is considered invalid.
 *
 * The program prints the resulting string on stdout, or one of the
 * diagnostic messages used by the original binary:
 *
 *      USAGE          – wrong number of arguments or input longer than 1023 bytes
 *      INVALID_MODE   – mode is not "escape" or "unescape"
 *      INVALID        – an invalid escape sequence was encountered while unescaping
 *
 * The original binary limited the input length to 0x3FF (1023) bytes and
 * kept the output in a static buffer large enough for the worst‑case
 * expansion (each input byte could become two output bytes).  The same
 * limits are reproduced here.
 */

#include <stdio.h>
#include <string.h>
#include <stdbool.h>

#define MAX_INPUT  1023                     /* 0x3FF – same limit as the original binary */
#define MAX_OUTPUT (MAX_INPUT * 2 + 1)      /* worst case: every byte becomes two */

static char main_out[MAX_OUTPUT];           /* buffer used by the original program */

/* --------------------------------------------------------------------- */
/* Escape a string ------------------------------------------------------ */
static bool do_escape(const char *src)
{
    size_t out_idx = 0;

    for (size_t i = 0; src[i] != '\0'; ++i) {
        unsigned char c = (unsigned char)src[i];

        if (c == '\\') {
            if (out_idx + 2 >= MAX_OUTPUT) return false;
            main_out[out_idx++] = '\\';
            main_out[out_idx++] = '\\';
        } else if (c == '"') {
            if (out_idx + 2 >= MAX_OUTPUT) return false;
            main_out[out_idx++] = '\\';
            main_out[out_idx++] = '"';
        } else if (c == '\n') {
            if (out_idx + 2 >= MAX_OUTPUT) return false;
            main_out[out_idx++] = '\\';
            main_out[out_idx++] = 'n';
        } else if (c == '\t') {
            if (out_idx + 2 >= MAX_OUTPUT) return false;
            main_out[out_idx++] = '\\';
            main_out[out_idx++] = 't';
        } else {
            if (out_idx + 1 >= MAX_OUTPUT) return false;
            main_out[out_idx++] = c;
        }
    }

    main_out[out_idx] = '\0';
    return true;
}

/* --------------------------------------------------------------------- */
/* Un‑escape a string ---------------------------------------------------- */
static bool do_unescape(const char *src)
{
    size_t out_idx = 0;
    size_t i = 0;

    while (src[i] != '\0') {
        if (src[i] != '\\') {
            if (out_idx + 1 >= MAX_OUTPUT) return false;
            main_out[out_idx++] = src[i++];
            continue;
        }
        /* we have a back‑slash – need a following character */
        if (src[i + 1] == '\0')
            return false;               /* trailing back‑slash -> invalid */

        char esc = src[i + 1];
        if (esc == '\\') {
            if (out_idx + 1 >= MAX_OUTPUT) return false;
            main_out[out_idx++] = '\\';
        } else if (esc == '"') {
            if (out_idx + 1 >= MAX_OUTPUT) return false;
            main_out[out_idx++] = '"';
        } else if (esc == 'n') {
            if (out_idx + 1 >= MAX_OUTPUT) return false;
            main_out[out_idx++] = '\n';
        } else if (esc == 't') {
            if (out_idx + 1 >= MAX_OUTPUT) return false;
            main_out[out_idx++] = '\t';
        } else {
            return false;               /* unknown escape sequence */
        }
        i += 2;   /* consumed the back‑slash and its partner */
    }

    main_out[out_idx] = '\0';
    return true;
}

/* --------------------------------------------------------------------- */
int main(int argc, char *argv[])
{
    /* The original binary required exactly three arguments:
       program name, mode, and the string to process. */
    if (argc != 3) {
        puts("USAGE");
        return 0;
    }

    const char *mode = argv[1];
    const char *input = argv[2];

    /* Input length limit – the original program printed USAGE if the
       string was longer than 0x3FF bytes. */
    if (strlen(input) > MAX_INPUT) {
        puts("USAGE");
        return 0;
    }

    if (strcmp(mode, "escape") == 0) {
        if (do_escape(input))
            puts(main_out);
        else
            puts("INVALID");
    } else if (strcmp(mode, "unescape") == 0) {
        if (do_unescape(input))
            puts(main_out);
        else
            puts("INVALID");
    } else {
        puts("INVALID_MODE");
    }

    return 0;
}
